<script setup lang="ts">
import { nextTick, onMounted, reactive, ref } from 'vue'
import type { CreateTaskInput, Project, TeamMember } from '../../types/dashboard'
const props=defineProps<{projects:Project[];members:TeamMember[]}>();const emit=defineEmits<{close:[];create:[task:CreateTaskInput]}>();const input=ref<HTMLInputElement|null>(null);const dialog=ref<HTMLElement|null>(null);const form=reactive<CreateTaskInput>({title:'',projectId:'',assigneeId:'',priority:'medium',dueDate:'',status:'todo'});const error=ref('')
function submit(){error.value=form.title&&form.projectId&&form.assigneeId&&form.dueDate?'':'請完成所有必填欄位。';if(!error.value)emit('create',{...form})}function trap(e:KeyboardEvent){if(e.key!=='Tab'||!dialog.value)return;const els=dialog.value.querySelectorAll<HTMLElement>('button,input,select,[tabindex]:not([tabindex="-1"])');const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}onMounted(()=>void nextTick(()=>input.value?.focus()))
</script>
<template><div class="modal" @mousedown.self="emit('close')"><section ref="dialog" role="dialog" aria-modal="true" aria-labelledby="task-modal-title" @keydown.esc="emit('close')" @keydown.tab="trap"><header><h2 id="task-modal-title">新增任務</h2><button type="button" aria-label="關閉新增任務視窗" @click="emit('close')">×</button></header><form @submit.prevent="submit"><label>任務名稱<input ref="input" v-model="form.title" /></label><label>所屬專案<select v-model="form.projectId"><option value="">請選擇專案</option><option v-for="project in props.projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><label>負責人<select v-model="form.assigneeId"><option value="">請選擇成員</option><option v-for="member in props.members" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label>優先度<select v-model="form.priority"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label>截止日期<input v-model="form.dueDate" type="date" /></label><label>狀態<select v-model="form.status"><option value="todo">待處理</option><option value="in-progress">進行中</option><option value="review">審核中</option><option value="done">已完成</option></select></label><p v-if="error" role="alert">{{ error }}</p><footer><button type="button" @click="emit('close')">取消</button><button type="submit">建立任務</button></footer></form></section></div></template>
<style scoped>.modal{align-items:center;background:rgb(15 23 42 / 45%);display:flex;inset:0;justify-content:center;padding:var(--space-4);position:fixed;z-index:40}.modal section{background:var(--color-surface);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);max-height:calc(100vh - 2rem);max-width:34rem;overflow:auto;padding:var(--space-6);width:100%}header{display:flex;justify-content:space-between}h2{margin:0}header button{background:transparent;border:0;font-size:1.5rem}form{display:grid;gap:var(--space-3);margin-top:var(--space-5)}label{color:var(--color-text-secondary);display:grid;font-size:.8125rem;font-weight:700;gap:var(--space-1)}input,select{border:1px solid var(--color-border);border-radius:var(--radius-md);font:inherit;min-height:2.5rem;padding:0 var(--space-2)}form p{color:var(--color-danger-strong);font-size:.75rem;margin:0}footer{display:flex;gap:var(--space-3);justify-content:flex-end}footer button{border:1px solid var(--color-border);border-radius:var(--radius-md);font:inherit;font-weight:700;min-height:2.5rem;padding:0 var(--space-4)}footer button:last-child{background:var(--color-accent);border-color:var(--color-accent);color:white}</style>
